O=G.copy()
for k,cells in enumerate(comps):
    s=set(cells); depth={}
    from collections import deque
    q=deque()
    for p in cells:
        r,c=p
        if any((r+dr,c+dc) not in s for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]):
            depth[p]=0;q.append(p)
    while q:
        r,c=q.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
